-- CLAIM ELEMENTS — SSDI
INSERT INTO claim_elements_matrix (element_id, claim_type, domain, statute, element_name, description, evidence_types, confidence_threshold, proof_standard, evidence_examples) VALUES
('ssdi_001','SSDI_Denial','BENEFITS','42 USC § 405','Severe Medical Condition','Applicant has a medical condition severe enough to prevent substantial gainful activity (SGA defined as earnings > $1,550/month in 2024)',ARRAY['medical_records','physician_testimony','functional_capacity_evaluation','imaging_studies'],0.75,'Clear and convincing evidence of impairment severity',ARRAY['Hospital discharge summaries','MRI/CT scans','Doctor''s functional assessment','Pain journals','Treatment records']),
('ssdi_002','SSDI_Denial','BENEFITS','42 USC § 405','Duration of Condition','Medical condition must last or be expected to last at least 12 months or result in death',ARRAY['medical_prognosis','physician_statement','treatment_duration'],0.70,'Physician opinion on prognosis with timeline',ARRAY['Doctor''s letter stating expected duration','Specialist prognosis','Treatment plan showing 12+ month duration']),
('ssdi_003','SSDI_Denial','BENEFITS','42 USC § 405','Work History & Coverage','Applicant worked enough years and recently enough to qualify for SSDI (typically 20 of last 40 quarters)',ARRAY['tax_returns','W2_forms','earnings_record','social_security_statement'],0.95,'SSA earnings record verification (automatic)',ARRAY['SSA statement of earnings','W-2s','Tax returns']),
('ssdi_004','SSDI_Denial','BENEFITS','42 USC § 405','Inability to Work at Substantial Gainful Level','Applicant cannot earn more than $1,550/month (2024 SGA limit) due to impairment',ARRAY['work_history','functional_limitations','medical_evidence','attempt_to_work_documentation'],0.80,'Functional capacity evidence showing inability to reach SGA',ARRAY['Functional capacity evaluation','Doctor''s statement of limitations','Job search attempts + documentation','Layoff/termination due to condition']),

