('mcaid_001','Medicaid_Wrongful_Denial','BENEFITS','42 USC § 1396a','Categorical Eligibility','Applicant falls within a covered category: low-income parent, pregnant woman, child, elderly, or disabled',ARRAY['family_documents','medical_documentation','birth_certificate','age_verification'],0.90,'Documentary evidence of categorical status',ARRAY['Birth certificate (child)','Pregnancy test results','SSDI award letter (disabled)']),
('mcaid_002','Medicaid_Wrongful_Denial','BENEFITS','42 USC § 1396a','Income Limit Compliance','Applicant''s income is below state Medicaid income limit (varies by state, typically 138% federal poverty line)',ARRAY['pay_stubs','tax_returns','unemployment_documents','bank_statements'],0.92,'3-month average income documentation',ARRAY['Recent pay stubs (if employed)','Tax return (if self-employed)','UI statement (if unemployed)']),
('mcaid_003','Medicaid_Wrongful_Denial','BENEFITS','42 USC § 1396a','Citizenship / Immigration Status','Applicant is US citizen OR qualified immigrant (varies by state)',ARRAY['birth_certificate','passport','green_card','SSN_documentation'],0.95,'Legal citizenship documentation',ARRAY['US birth certificate','Passport','Green card','REAL ID compliant driver''s license']),
('mcaid_004','Medicaid_Wrongful_Denial','BENEFITS','42 USC § 1396a','Residency','Applicant is state resident (varies by state residency requirement)',ARRAY['address_proof','lease_agreement','utility_bill','voting_registration'],0.85,'Any two forms of address documentation',ARRAY['Lease/mortgage (recent)','Utility bill (recent)','Mail from government agency','Voter registration']),

