('housing_001','Housing_Discrimination','CIVIL_RIGHTS','42 USC § 3601','Protected Class Status','Applicant belongs to protected class: race, color, national origin, religion, sex, familial status, disability',ARRAY['visual_identification','self_identification','family_documents'],0.95,'Applicant testimony or documentary evidence',ARRAY['Applicant testimony','Birth certificate showing race/ethnicity','Medical documentation of disability']),
('housing_002','Housing_Discrimination','CIVIL_RIGHTS','42 USC § 3601','Housing Availability','Landlord was advertising or had available housing unit at time of alleged discrimination',ARRAY['listing_screenshots','craigslist_posts','lease_offered_to_others','landlord_testimony'],0.90,'Documentary evidence the unit was available',ARRAY['Listing showing ''Available Now''','Screenshots from Zillow/Craigslist','Lease signed by someone else for same unit']),
('housing_003','Housing_Discrimination','CIVIL_RIGHTS','42 USC § 3601','Adverse Action','Landlord denied application, lease, or facility access based on protected status',ARRAY['denial_letter','applicant_testimony','witness_testimony','landlord_statements'],0.85,'Clear rejection of housing application or access',ARRAY['Denial letter from landlord','Witness testimony of oral rejection','Email/text messages showing denial']),
('housing_004','Housing_Discrimination','CIVIL_RIGHTS','42 USC § 3601','Causal Connection','Adverse action was motivated by protected status (not legitimate reason)',ARRAY['comparative_treatment','landlord_statements','pattern_evidence','testing_evidence'],0.75,'Circumstantial evidence of discriminatory motive',ARRAY['Landlord admitted to race concern','Evidence landlord rented to similar non-protected applicants','Testing: White tester approved, Black tester denied']),

