('emp_discrim_003','Employment_Discrimination','CIVIL_RIGHTS','42 USC § 2000e','Adverse Employment Action','Employer took adverse action: non-hire, termination, demotion, reduced pay, harassment',ARRAY['termination_letter','payroll_records','employment_records','witness_testimony'],0.92,'Documentary evidence of adverse action',ARRAY['Termination letter','Payroll showing wage reduction','Email from manager denying promotion']),
