('wage_002','Wage_Theft_Unpaid_Wages','EMPLOYMENT','29 USC § 201 et seq','Work Performed','Worker performed work for employer; work was part of employer''s business',ARRAY['testimony','timesheets','email_communications','witness_testimony','work_product'],0.85,'Credible evidence of hours worked',ARRAY['Worker testimony of hours','Timesheet (even informal)','Emails about work assignments','Coworker testimony','Photos of work completed']),
('wage_003','Wage_Theft_Unpaid_Wages','EMPLOYMENT','29 USC § 201 et seq','Unpaid or Underpaid Wages','Worker was paid less than minimum wage or overtime rate, or not paid at all',ARRAY['pay_stubs','bank_records','employer_statements','time_records'],0.88,'Wage calculation showing shortfall vs statutory minimum/overtime',ARRAY['Pay stub showing hours worked vs amount paid','Bank deposits less than hours worked','Employer email confirming unpaid hours']),
