('ins_004','Insurance_Coverage_Denial','HEALTHCARE','42 USC § 300gg et seq','Denial Was Wrongful','Insurer''s denial violated policy, law, or standard of care review',ARRAY['denial_letter','policy_analysis','expert_review','appeals_documentation'],0.75,'Denial contradicts policy language or violates ACA standards',ARRAY['Denial letter doesn''t match policy exclusions','Insurer applied wrong policy version','Reviewer was not physician despite medical determination required']),

