('foia_001','FOIA_Wrongful_Withholding','OVERSIGHT','5 USC § 552','Timely FOIA Request','Claimant made FOIA request complying with statutory requirements',ARRAY['foia_request_letter','agency_acknowledgment','request_tracking_number'],0.95,'Request meets statutory specificity and administrative requirements',ARRAY['FOIA request letter naming agency','Tracking number from agency','Email confirmation of receipt']),
('foia_002','FOIA_Wrongful_Withholding','OVERSIGHT','5 USC § 552','Agency Custody of Records','Named agency has or had custody/control of responsive records',ARRAY['agency_statement','record_evidence','testimony'],0.90,'Records exist within agency files or are reasonably locatable',ARRAY['Records referenced in agency decisions','Agency email chains','Internal documents']),
