-- STATUTES
INSERT INTO statutes_registry (statute_id, statute_number, statute_title, domain, jurisdiction, enacted, enforcement_agency, application_scope, key_clauses, claim_types_covered, statute_of_limitations, state_variation, website) VALUES
('benefits_001','42 USC § 301 et seq','Old Age, Survivors, and Disability Insurance (Social Security Act)','BENEFITS','federal','1935; amended multiple times through 2024','Social Security Administration (SSA)','Federal; applies nationwide. Covers retirement, survivors, disability insurance (SSDI) and Supplemental Security Income (SSI)','["§ 405: Appeals and judicial review of SSA determinations","§ 406: Attorney fees (capped at $6,000 or 25% of backpay, whichever is lower)","§ 423: Standards for disability determination (severe impairment lasting 12+ months)"]'::jsonb,ARRAY['SSDI_Denial','SSI_Denial','benefits_wrongful_termination'],'60 days for initial filing; no limit for ongoing appeals',NULL,'ssa.gov'),
('benefits_002','42 USC § 1396 et seq','Medicaid (Title XIX of Social Security Act)','BENEFITS','federal','1965; continuously amended','Centers for Medicare & Medicaid Services (CMS); state Medicaid agencies','Federal-state partnership; each state sets income/asset limits within federal minimums','["§ 1396a: Medicaid eligibility requirements","§ 1396d: Medicaid services covered","§ 1396n: Waivers for home and community-based services"]'::jsonb,ARRAY['Medicaid_Denial','Medicaid_Wrongful_Termination'],'No federal limit; state administrative appeals 30-90 days; federal review 2 years','Significant — income limits, asset tests, categorical eligibility vary by state','medicaid.gov'),
('benefits_003','7 USC § 2011 et seq','Supplemental Nutrition Assistance Program (SNAP)','BENEFITS','federal','1964; renamed 2008','USDA Food and Nutrition Service (FNS); state human services departments','Federal-state program. Income limit: 130% federal poverty line; asset limit: $2,500 (most states)','["§ 2015: Eligibility determination","§ 2020: Benefit amounts","§ 2022: Disqualifications"]'::jsonb,ARRAY['SNAP_Denial','SNAP_Wrongful_Termination'],'No federal limit; state appeal 30 days from notice; federal court review available',NULL,'fns.usda.gov/snap'),
('benefits_004','15 USC § 1601 et seq','Fair Debt Collection Practices Act (FDCPA)','BENEFITS','federal','1977','Federal Trade Commission (FTC); private right of action','Federal; applies to debt collectors. Covers phone calls, letters, threats, harassment','["§ 1692d: Prohibition on harassment, abuse, threats","§ 1692e: False or misleading representations","§ 1692g: Required debt verification","§ 1692k: Damages ($1,000 per lawsuit statutory; actual damages; attorney fees)"]'::jsonb,ARRAY['Debt_Collection_Violation'],'1 year from violation',NULL,'ftc.gov/articles/debt-collection'),
('civil_rights_001','42 USC § 2000e et seq','Title VII of the Civil Rights Act of 1964 (Employment Discrimination)','CIVIL_RIGHTS','federal','1964; amended by Civil Rights Act of 1991','Equal Employment Opportunity Commission (EEOC)','Federal; applies to employers with 15+ employees. Prohibits discrimination based on race, color, religion, sex, national origin','["§ 2000e-2: Unlawful employment practices","§ 2000e-5: EEOC charge filing (180 or 300 days)","§ 2000e-5(k): Right to Sue","§ 2000e-5(l): Damages (back pay, compensatory $50K-$300K cap, punitive, attorney fees)"]'::jsonb,ARRAY['Employment_Discrimination','Wrongful_Termination_Retaliation'],'180 or 300 days to file EEOC charge (varies by state)',NULL,'eeoc.gov'),
('civil_rights_002','42 USC § 3601 et seq','Fair Housing Act (FHA)','CIVIL_RIGHTS','federal','1968; amended 1988 (Fair Housing Amendments Act)','HUD Office of Fair Housing and Equal Opportunity (FHEO)','Federal; applies to housing discrimination based on race, color, national origin, religion, sex, familial status, disability','["§ 3603: Prohibited discrimination in housing","§ 3604: Discrimination in sale, rental, financing","§ 3613: Private right of action (damages + attorney fees)","§ 3614: HUD administrative proceedings (damages up to $16,000)"]'::jsonb,ARRAY['Housing_Discrimination','Housing_Denial'],'1 year from violation (for private suit); 1 year for HUD complaint',NULL,'hud.gov/fairhousing'),
('civil_rights_003','42 USC § 1983','Civil Rights Act of 1871 (Section 1983 civil rights action)','CIVIL_RIGHTS','federal','1871 (Ku Klux Klan Act); codified 1994','Private right of action (not government-enforced); federal courts','Federal; applies to government officials acting under color of law. Covers deprivation of constitutional or statutory rights','["§ 1983: Cause of action for deprivation of rights","§ 1988: Attorney fees (mandatory if prevail in civil rights action)","Qualified Immunity doctrine: Officers have immunity unless rights were ''clearly established''"]'::jsonb,ARRAY['Police_Accountability','Government_Misconduct','Civil_Rights_Violation'],'3 years (applies most state longer SOL, whichever is longer)',NULL,'justice.gov/civil-rights'),
('employment_001','29 USC § 201 et seq','Fair Labor Standards Act (FLSA)','EMPLOYMENT','federal','1938; amended multiple times','Department of Labor Wage & Hour Division (WHD)','Federal; applies to employers engaged in interstate commerce. Covers minimum wage, overtime, child labor','["§ 206: Federal minimum wage ($7.25/hour; states may set higher)","§ 207: Maximum hours and overtime (40 hrs/week @ 1.5x pay)","§ 215: Unlawful act (wage withholding)","§ 216: Penalties (back wages + liquidated damages + attorney fees)"]'::jsonb,ARRAY['Wage_Theft','Unpaid_Overtime','Minimum_Wage_Violation'],'3 years for back wages (2 years if non-willful)',NULL,'dol.gov/whd'),
('employment_002','29 USC § 651 et seq','Occupational Safety and Health Act (OSHA)','EMPLOYMENT','federal','1970','Occupational Safety and Health Administration (OSHA); state OSHA programs','Federal (+ state plans in some states). Covers workplace safety hazards; whistleblower protection','["§ 660: OSH Standards","§ 666: Occupational Safety and Health standards","§ 704: Whistleblower protection (retaliation for safety complaint prohibited; 30-day deadline to file)"]'::jsonb,ARRAY['Wrongful_Termination_Retaliation','Workplace_Safety_Violation'],'30 days to file OSHA retaliation complaint (strict deadline)',NULL,'osha.gov'),
('employment_003','29 USC § 2601 et seq','Family and Medical Leave Act (FMLA)','EMPLOYMENT','federal','1993','Department of Labor Wage & Hour Division','Federal; applies to employers with 50+ employees. Requires unpaid, job-protected leave','["§ 2614: FMLA rights (up to 12 weeks unpaid leave/year)","§ 2615: Prohibited acts (employer cannot retaliate for FMLA use)","§ 2617: Damages (back pay, reinstatement, damages)"]'::jsonb,ARRAY['FMLA_Violation','Wrongful_Termination_Retaliation'],'2 years (3 years for willful violation)',NULL,'dol.gov/agencies/whd/fmla'),
('healthcare_001','42 USC § 300gg et seq','Affordable Care Act (ACA) - Health Insurance Coverage Requirements','HEALTHCARE','federal','2010; amended multiple times through 2024','Centers for Medicare & Medicaid Services (CMS); HHS Office for Civil Rights; state insurance commissioners','Federal; applies to health insurance plans. Requires coverage of preventive services, mental health parity, no lifetime limits','["§ 2711: Preventive health services (no cost-sharing)","§ 2712: Dependent coverage (age 26)","§ 300gg-13: Mental Health Parity Act","§ 300gg-19: Prohibition on lifetime limits"]'::jsonb,ARRAY['Healthcare_Coverage_Denial','Mental_Health_Parity_Violation'],'No federal limit; administrative appeals vary (30-90 days)',NULL,'healthcare.gov'),
('oversight_001','5 USC § 552','Freedom of Information Act (FOIA)','OVERSIGHT','federal','1966; amended multiple times through 2024','Agency FOIA officers; federal courts (for enforcement)','Federal; applies to all federal agencies. Requires release of non-exempt records within 20 days','["§ 552(a)(3): FOIA request procedures","§ 552(a)(4): Agency response timeline (20 days + possible 10-day extension)","§ 552(b): Exemptions (9 total: national security, internal deliberations, trade secrets, privacy, etc)","§ 552(a)(4)(B): Judicial review","28 USC § 2412: Attorney fees (if plaintiff substantially prevails)"]'::jsonb,ARRAY['FOIA_Wrongful_Withholding','FOIA_Delay'],'Administrative appeal: 20 days; federal court: 6 years',NULL,'foia.gov'),
('oversight_002','5 USC § 551 et seq','Administrative Procedure Act (APA)','OVERSIGHT','federal','1946','Federal courts (judicial review); agency administrative law judges','Federal; applies to all federal agency rulemaking, adjudication, licensing decisions','["§ 553: Rulemaking (notice-and-comment requirement)","§ 554: Adjudication (hearing rights)","§ 706: Judicial review (arbitrary and capricious, abuse of discretion)"]'::jsonb,ARRAY['Government_Misconduct','Regulatory_Capture','Agency_Abuse'],'6 years',NULL,'justice.gov/atr'),
('oversight_003','41 USC § 4501 et seq','Whistleblower Protection Act','OVERSIGHT','federal','1989; amended 2002 (Sarbanes-Oxley), 2010 (Dodd-Frank)','Occupational Safety and Health Administration (OSHA) whistleblower program','Federal; protects employees who report violations of law, regulation, rule, or unsafe working conditions','["§ 4504: Whistleblower protection (prohibition on retaliation)","§ 4505: Remedy (reinstatement, back pay, damages for retaliation)"]'::jsonb,ARRAY['Whistleblower_Retaliation','Government_Accountability'],'30 days to file with OSHA (strict deadline)',NULL,'osha.gov/whistleblowers');

